// Continuum 93 C compiler internals, a line-by-line port of the reference's Emulator/Compilers/C93C:
//   cc_pp.cpp     CLexer.cs, CPreprocessor.cs, CConstExpr.cs
//   cc_parse.cpp  CParser.cs, CTypes.cs, CAst.cs
//   cc_gen.cpp    CCodeGen.cs, CCompiler.cs, CRuntime.cs (cc_runtime.inc is generated by tests/oracle --ccruntime)
// Output (assembly text, errors, log) is identical to the reference's (tests/oracle --cc, conformance --cc).
// Text is UTF-8; where the reference counted or truncated UTF-16 units (columns, string literal bytes,
// character constants) the port converts. Reproduced quirks:
//  - String literal bytes are the low byte of each UTF-16 unit ("é" -> 0xE9, "€" -> 0xAC).
//  - #pragma once is keyed by the name the file was included as; the main file by its own name.
//  - Included tokens carry the include *name* as their file (errors say "hal_core.h:3:1"), and the include
//    resolver gets that name as the including file.
//  - An array declarator in a nested declarator ("int (*p)[N]") is parsed twice: string literals and
//    temporaries in N are created twice (labels shift).
//  - Brace elision wins over struct-from-expression in lists ("struct S a[2] = { s1, s2 }" fills members).
//  - "for (typedef ...;" declares variables. A typedef name followed by ':' is a label.
//  - Errors on the first problem in the parser and code generator (the reference throws CCompileAbort).
//  - Where the reference threw a .NET exception (null function in a global initializer's compound assignment,
//    int.MinValue / -1 in a constant, a token read past the end, an unsized store), CcResult.fatal is set.
// Not reproduced: Unicode letter/digit tables beyond Latin-1 (other non-ASCII BMP characters count as
// letters outside the punctuation/symbol blocks), astral-plane characters outside literals and comments.
#pragma once
#include <cstdint>
#include <deque>
#include <memory>
#include <new>
#include <type_traits>
#include <string>
#include <string_view>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>

#include "cc.h"

namespace c93::cc {

struct Abort {};                     // CCompileAbort: the error is already recorded
struct Fatal { std::string what; };  // the reference threw a .NET exception
[[noreturn]] inline void fatal(std::string what) { throw Fatal{std::move(what)}; }
[[noreturn]] void outOfRange();   // a token read past the end (cold path, keeps Parser::cur inlined)

using Errors = std::vector<CcError>;

// ---------------------------------------------------------------------------- tokens (CLexer.cs)
enum class TK { Identifier, Number, Char, String, Punct, Newline, Eof };
using HideSet = std::shared_ptr<const std::vector<std::string>>;   // sorted; null = empty

struct Token {
    TK kind = TK::Eof;
    std::string text;                // String/Char: the decoded value (UTF-8)
    const std::string* file = nullptr;
    int line = 1, col = 1;
    bool leadingSpace = false;
    HideSet hide;
    bool is(std::string_view s) const { return (kind == TK::Punct || kind == TK::Identifier) && text == s; }
    std::string str() const;         // CToken.ToString
};

// Interned file names, so tokens carry a pointer (stable: deque).
struct Files {
    std::deque<std::string> names;
    const std::string* intern(const std::string& n) {
        for (auto& s : names) if (s == n) return &s;
        return &names.emplace_back(n);
    }
};

// Stable-address storage in blocks of 256 (MSVC's std::deque allocates every element over 8 bytes alone).
template <class T> class Pool {
public:
    template <class... A> T& emplace_back(A&&... a) {
        if (used_ == kBlock || blocks_.empty()) { blocks_.emplace_back(new Slot[kBlock]); used_ = 0; }
        void* at = blocks_.back()[used_++].b;
        if constexpr (std::is_constructible_v<T, A...>) return *new (at) T(std::forward<A>(a)...);
        else return *new (at) T{std::forward<A>(a)...};
    }
    size_t size() const { return blocks_.empty() ? 0 : (blocks_.size() - 1) * kBlock + used_; }
    ~Pool() {
        for (size_t i = 0; i < blocks_.size(); ++i)
            for (size_t k = 0, n = i + 1 == blocks_.size() ? used_ : kBlock; k < n; ++k) reinterpret_cast<T*>(blocks_[i][k].b)->~T();
    }
private:
    static constexpr size_t kBlock = 256;
    struct Slot { alignas(T) unsigned char b[sizeof(T)]; };
    std::vector<std::unique_ptr<Slot[]>> blocks_;
    size_t used_ = 0;
};

// The preprocessor's output: tokens live in a pool, the list holds pointers (no moves when it grows).
using TokenList = std::vector<const Token*>;

std::vector<Token> tokenize(std::string_view src, const std::string* file, Errors& errors);

// UTF-8 text seen as the reference's UTF-16 string.
size_t utf16Length(std::string_view s);
std::vector<uint8_t> lowBytes(std::string_view s);   // (byte)c for every UTF-16 unit c
std::string utf8(uint32_t cp);

bool tryParseInt(const std::string& text, uint32_t& value, bool& isUnsigned, std::string& error);   // CConstExpr.TryParseInt

class Preprocessor {   // CPreprocessor.cs
public:
    using Resolver = std::function<std::optional<std::string>(const std::string&, const std::string&)>;
    Preprocessor(Files& files, Pool<Token>& store, Resolver resolve, Errors& errors);
    TokenList process(std::string_view source, const std::string& file);
    std::vector<std::pair<std::string, Token>> pragmas;   // "#pragma c93 <name> <value>", insertion order

private:
    struct Macro { std::string name; bool functionLike = false, variadic = false; std::vector<std::string> params; std::vector<Token> body; };
    struct Cond { bool parentActive, active, anyTaken, seenElse = false; };
    Files& files_;
    Pool<Token>& store_;
    std::vector<Token> run_;   // expansion of the current text run, before it moves to store_
    Resolver resolve_;
    Errors& errors_;
    std::unordered_map<std::string, Macro> macros_;
    std::unordered_set<std::string> pragmaOnce_;
    int includeDepth_ = 0;

    void define(const std::string& name, const std::string& value);
    void processFile(std::string_view source, const std::string& file, TokenList& out);
    void directive(std::vector<Token>& line, const std::string& file, std::vector<Cond>& conds, bool active, TokenList& out);
    void handleDefine(const std::vector<Token>& args, const Token& dirTok);
    void handleInclude(const std::vector<Token>& args, const Token& dirTok, const std::string& file, TokenList& out);
    bool evaluate(const std::vector<Token>& args, const Token& dirTok);
    std::vector<Token> expand(std::vector<Token> input);
    void expand(Token* in, Token* end, std::vector<Token>& out);
    std::vector<Token> substitute(const Macro& m, const std::vector<std::vector<Token>>* actuals, const HideSet& hs, const Token& site);
    std::vector<Token> paste(std::vector<Token> left, std::vector<Token> right, const Token& site);
    void error(const Token& at, std::string message);
};

// ---------------------------------------------------------------------------- types (CTypes.cs)
enum class TyK { Void, Char, Short, Int, Pointer, Array, Struct, Function };
struct Type;
struct Member { std::string name; bool anonymous = false; Type* type = nullptr; int offset = 0; };
struct StructInfo {
    std::string tag; bool hasTag = false;
    bool isUnion = false, complete = false;
    std::vector<Member*> members;
    int size = 0;
    Member* find(const std::string& n) const { for (Member* m : members) if (!m->anonymous && m->name == n) return m; return nullptr; }
};
struct Param { std::string name; bool hasName = false; Type* type = nullptr; };

struct Type {
    TyK kind = TyK::Void;
    bool uns = false;
    Type* base = nullptr;
    int length = -1;
    StructInfo* st = nullptr;
    std::vector<Param> params;
    bool hasProto = false, variadic = false, isEnum = false, isBool = false;

    bool isInteger() const { return kind == TyK::Char || kind == TyK::Short || kind == TyK::Int; }
    bool isPointer() const { return kind == TyK::Pointer; }
    bool isArray() const { return kind == TyK::Array; }
    bool isStruct() const { return kind == TyK::Struct; }
    bool isFunction() const { return kind == TyK::Function; }
    bool isVoid() const { return kind == TyK::Void; }
    bool isScalar() const { return isInteger() || isPointer(); }
    bool isComplete() const;
    int size() const;
    std::string str() const;
};
bool sameType(const Type* a, const Type* b);

// ---------------------------------------------------------------------------- AST (CAst.cs)
enum class SymK { Global, Local, Function, EnumConst, Typedef };
struct Function;
struct Reloc { int offset; std::string target; int64_t addend; };
struct Symbol {
    std::string name;
    SymK kind = SymK::Global;
    Type* type = nullptr;
    std::string label;
    int offset = 0;
    int64_t enumValue = 0;
    bool isDefined = false, isStatic = false, isExtern = false, isReferenced = false, hasInit = false;
    std::vector<uint8_t> initData;
    std::vector<Reloc> relocs;
    Function* fn = nullptr;
};

// HashSet<string> as the reference iterates it (insertion order, nothing is ever removed).
struct LabelSet {
    std::vector<std::string> order;
    std::unordered_set<std::string> has;
    void add(const std::string& s) { if (has.insert(s).second) order.push_back(s); }
};

struct Node;
struct Function {
    std::string name;
    Symbol* sym = nullptr;
    Type* type = nullptr;
    std::vector<Symbol*> params, locals;
    Node* body = nullptr;
    int frameSize = 0;
    std::string returnLabel;
    LabelSet called;
};

enum class NK {
    Num, Var, StrLabel, FuncAddr, Deref, Addr, Neg, BitNot, LogNot,
    Add, Sub, Mul, Div, Mod, Shl, Shr, BitAnd, BitOr, BitXor, Eq, Ne, Lt, Le, LogAnd, LogOr,
    Cond, Comma, Assign, Member, Cast, Call, MemZero,
    Block, ExprStmt, If, For, Do, Switch, Case, Goto, Label, Return, Asm, Empty
};
const char* nodeKindName(NK k);

struct Node {   // ~200 bytes: labels are numbers (".c__L<n>"), one list and one text per kind
    NK kind;
    Type* type = nullptr;
    const Token* tok = nullptr;
    Node *lhs = nullptr, *rhs = nullptr;
    Node *cond = nullptr, *then = nullptr, *els = nullptr, *init = nullptr, *inc = nullptr, *bodyStmt = nullptr;
    std::vector<Node*> list;            // Block statements, Switch cases, Call arguments
    int breakLabel = -1, continueLabel = -1, uniqueLabel = -1;
    Node* defaultCase = nullptr;
    int64_t value = 0;                  // Num value, Case value
    std::string text;                   // StrLabel label, Goto/Label user name, Asm text
    Symbol* var = nullptr;
    Member* member = nullptr;
    Type* funcType = nullptr;
    Symbol* directCallee = nullptr;
};

struct Unit {
    std::vector<Symbol*> globals;
    std::vector<Function*> functions;
    std::vector<std::pair<std::string, std::vector<uint8_t>>> strings;
};

// Owns every type, node, symbol and token list of one compilation.
struct Arena {
    Pool<Type> types;
    Pool<StructInfo> structs;
    Pool<Member> members;
    Pool<Node> nodes;
    Pool<Symbol> symbols;
    Pool<Function> functions;
    Pool<Token> tokens;
    Pool<TokenList> tokenLists;
    Files files;
    Type* type(const Type& t) { return &types.emplace_back(t); }
    Node* node(NK k, const Token* tok) { Node& n = nodes.emplace_back(); n.kind = k; n.tok = tok; return &n; }
};

// Shared basic types (CType.Void, CType.Int...). Never modified.
extern Type tVoid, tBool, tChar, tUChar, tShort, tUShort, tInt, tUInt;

class Parser;   // cc_parse.cpp
struct ParseResult { int labelCounter; Symbol* main; };
// Parses the user's tokens, then the runtime library's (library mode: user definitions win).
ParseResult parse(Arena& a, Unit& unit, Errors& errors, TokenList& user, TokenList& library,
                  const std::function<void()>& between);

} // namespace c93::cc
